-- Tabelas
create table public.curso (
  id           bigint generated by default as identity primary key,
  curso        text not null,
  descricao    text,
  conteudo     text,
  carga_horaria text,
  categoria    text,
  nivel        text,
  ativo        boolean default true
);
create table public.user_curso (
  id       bigint generated by default as identity primary key,
  id_user  bigint not null references public.user(id) on delete cascade,
  id_curso bigint not null references public.curso(id) on delete cascade,
  status   text not null default 'pendente',
  unique(id_user, id_curso)
);
alter table public.curso enable row level security;
create policy "allow all" on public.curso for all using (true) with check (true);
alter table public.user_curso enable row level security;
create policy "allow all" on public.user_curso for all using (true) with check (true);

-- Cursos
